// ============================================================================
// n8n CODE NODE: Stage 2 Command Parser
// ============================================================================
// 
// INPUT: Stage 2 LLM output (markdown-wrapped JSON with commands arrays)
// OUTPUT: Validated command sequences ready for execution
//
// Setup in n8n:
// 1. Connect from Stage 2 LLM node
// 2. Set Mode: "Run Once for All Items"
// 3. Expected input: items[0].json.output
// ============================================================================

const rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error('❌ No output from Stage 2. Expected json.output field.');
}

// Parse JSON (strip markdown if needed)
let jsonString = typeof rawOutput === 'string' ? rawOutput : String(rawOutput);
jsonString = jsonString.trim();
jsonString = jsonString.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
jsonString = jsonString.trim();

const jsonStart = jsonString.indexOf('{');
const jsonEnd = jsonString.lastIndexOf('}');

if (jsonStart === -1 || jsonEnd === -1) {
  throw new Error('❌ No JSON object found in Stage 2 output');
}

jsonString = jsonString.substring(jsonStart, jsonEnd + 1);

let compiledPlan;
try {
  compiledPlan = JSON.parse(jsonString);
} catch (parseError) {
  throw new Error(`❌ Invalid JSON in Stage 2: ${parseError.message}`);
}

// === VALIDATION ===

if (!compiledPlan.stages || typeof compiledPlan.stages !== 'object') {
  throw new Error('❌ Missing or invalid stages object');
}

const stageKeys = Object.keys(compiledPlan.stages)
  .map(k => parseInt(k))
  .sort((a, b) => a - b);

if (stageKeys.length === 0) {
  throw new Error('❌ No stages found in compiled plan');
}

// Validate command structure in each stage
let totalCommands = 0;
const commandStats = {
  equip: 0,
  place: 0,
  dig: 0,
  wait: 0,
  invalid: 0
};

const validActions = ['craft', 'smelt', 'equip', 'place', 'break', 'digDown', 'activate', 'useDoor'];

for (let stageNum of stageKeys) {
  const stage = compiledPlan.stages[stageNum.toString()];

  for (let workerNum = 1; workerNum <= 2; workerNum++) {
    const worker = stage[`Worker${workerNum}`];

    if (!worker) continue;
    if (!worker.commands || !Array.isArray(worker.commands)) {
      throw new Error(`❌ Stage ${stageNum} Worker${workerNum} missing or invalid commands array`);
    }

    if (worker.commands.length === 0) {
      console.warn(`⚠️  Stage ${stageNum} Worker${workerNum} has no commands`);
      continue;
    }

    // Validate each command
    for (let i = 0; i < worker.commands.length; i++) {
      const cmd = worker.commands[i];
      totalCommands++;

      // Check required fields
      if (!cmd.action) {
        throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: missing 'action'`);
      }

      if (!validActions.includes(cmd.action)) {
        throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: invalid action '${cmd.action}' (valid: equip, place, dig, wait)`);
      }

      commandStats[cmd.action]++;

      // Validate action-specific fields
      if (cmd.action === 'equip') {
        if (!cmd.item || typeof cmd.item !== 'string') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: equip requires 'item' string`);
        }
      }

      if (cmd.action === 'place') {
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: place requires x, y, z as numbers`);
        }
        // Validate coordinates are integers
        if (!Number.isInteger(cmd.x) || !Number.isInteger(cmd.y) || !Number.isInteger(cmd.z)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: coordinates must be integers`);
        }
      }

      if (cmd.action === 'dig') {
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: dig requires x, y, z as numbers`);
        }
        if (!Number.isInteger(cmd.x) || !Number.isInteger(cmd.y) || !Number.isInteger(cmd.z)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: coordinates must be integers`);
        }
      }

      if (cmd.action === 'craft' || cmd.action === 'smelt') {
        if (typeof cmd.item !== 'string' || cmd.item.length === 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: ${cmd.action} requires 'item' string`);
        }
        if (typeof cmd.quantity !== 'number' || cmd.quantity <= 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: ${cmd.action} quantity must be positive integer`);
        }
      }

      if (cmd.action === 'equip') {
        if (typeof cmd.item !== 'string' || cmd.item.length === 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: equip requires 'item' string`);
        }
      }

      if (cmd.action === 'place') {
        if (typeof cmd.material !== 'string' || cmd.material.length === 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: place requires 'material' string`);
        }
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: place requires x, y, z coordinates`);
        }
        if (!Number.isInteger(cmd.x) || !Number.isInteger(cmd.y) || !Number.isInteger(cmd.z)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: place coordinates must be integers`);
        }
      }

      if (cmd.action === 'break') {
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: break requires x, y, z coordinates`);
        }
        if (!Number.isInteger(cmd.x) || !Number.isInteger(cmd.y) || !Number.isInteger(cmd.z)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: break coordinates must be integers`);
        }
      }

      if (cmd.action === 'placeSpecial') {
        const specialBlocks = ['oak_door', 'spruce_door', 'birch_door', 'jungle_door', 'acacia_door', 'dark_oak_door', 'iron_door',
          'oak_trapdoor', 'spruce_trapdoor', 'birch_trapdoor', 'jungle_trapdoor', 'acacia_trapdoor', 'dark_oak_trapdoor', 'iron_trapdoor',
          'oak_stairs', 'spruce_stairs', 'birch_stairs', 'jungle_stairs', 'acacia_stairs', 'dark_oak_stairs', 'stone_stairs', 'brick_stairs',
          'glass_pane', 'glass', 'oak_slab', 'stone_slab', 'brick_slab'];

        if (!specialBlocks.includes(cmd.item)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: '${cmd.item}' not a valid special block`);
        }
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: placeSpecial requires x, y, z coordinates`);
        }
        if (!cmd.face || !['top', 'bottom', 'north', 'south', 'east', 'west'].includes(cmd.face)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: placeSpecial requires valid 'face'`);
        }
        if (cmd.facing && !['north', 'south', 'east', 'west'].includes(cmd.facing)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: placeSpecial 'facing' must be north, south, east, or west`);
        }
      }

      if (cmd.action === 'digDown') {
        if (typeof cmd.distance !== 'number' || cmd.distance <= 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: digDown requires positive 'distance'`);
        }
        if (!Number.isInteger(cmd.distance)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: digDown distance must be integer`);
        }
      }

      if (cmd.action === 'activate') {
        if (typeof cmd.blockType !== 'string' || cmd.blockType.length === 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: activate requires 'blockType' string`);
        }
      }

      if (cmd.action === 'useDoor') {
        if (typeof cmd.x !== 'number' || typeof cmd.y !== 'number' || typeof cmd.z !== 'number') {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: useDoor requires x, y, z coordinates`);
        }
        if (!Number.isInteger(cmd.x) || !Number.isInteger(cmd.y) || !Number.isInteger(cmd.z)) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: useDoor coordinates must be integers`);
        }
      }

      if (cmd.action === 'wait') {
        if (typeof cmd.seconds !== 'number' || cmd.seconds <= 0) {
          throw new Error(`❌ Stage ${stageNum} Worker${workerNum} Command ${i}: wait requires positive 'seconds'`);
        }
      }
    }
  }
}

// === SUCCESS ===

console.log('✅ Stage 2 commands parsed successfully');
console.log(`   Total commands: ${totalCommands}`);
console.log(`   Breakdown: ${commandStats.equip} equip, ${commandStats.place} place, ${commandStats.dig} dig, ${commandStats.wait} wait`);
console.log(`   Stages: ${stageKeys.length}`);

// Return compiled plan with validation metadata
return {
  success: true,
  compiledPlan: compiledPlan,
  commandStats: commandStats,
  validation: {
    totalCommands: totalCommands,
    stageCount: stageKeys.length,
    equipCommands: commandStats.equip,
    placeCommands: commandStats.place,
    digCommands: commandStats.dig,
    waitCommands: commandStats.wait,
    readyForExecution: true
  }
};

